from decimal import Decimal
from typing import Any, Callable


Guard = Callable[[dict, dict], bool]


def _numeric(value: Any) -> Decimal:
    """Apply the legacy empty/null-to-zero numeric coercion."""
    if value is None or value == "":
        return Decimal(0)
    if isinstance(value, Decimal):
        return value
    return Decimal(str(value))


def _approve_guard(record: dict, tables: dict) -> bool:
    # NVL(TOT_AMT, 0) > 0
    return _numeric(record.get("TOT_AMT", "")) > Decimal(0)


def _lookup_acct_credit_hold(record: dict, tables: dict) -> Any:
    key_value = record.get("ACCT_ID", "")
    rows = tables.get("ACCT_MASTER", [])

    for row in rows:
        if row.get("DEL_FLG", "") == "Y":
            continue
        if row.get("ACCT_ID", "") == key_value:
            return row.get("CRED_HOLD", "")

    return ""


def _approved_cancel_guard(record: dict, tables: dict) -> bool:
    # LOOKUP(...) <> 'Y'; blank boolean values mean N.
    return _lookup_acct_credit_hold(record, tables) != "Y"


def _always(record: dict, tables: dict) -> bool:
    return True


# Document order from legacy/order_fulfilment.xml.
_TRANSITIONS: tuple[
    tuple[str, str, str, Guard, tuple[str, ...], tuple[str, ...]], ...
] = (
    ("E", "approve", "A", _approve_guard, ("ORD_APPR",), ()),
    ("A", "ship", "S", _always, ("ORD_SHIP",), ("shipped",)),
    ("S", "invoice", "I", _always, ("ORD_INV",), ()),
    ("E", "cancel", "X", _always, ("ORD_CANC",), ()),
    ("A", "cancel", "X", _approved_cancel_guard, ("ORD_CANC",), ()),
    ("I", "cancel", "X", _always, ("ORD_CANC_INV",), ("credit_note",)),
)


def fire(state: str, event: str, record: dict, tables: dict) -> dict:
    record_copy = dict(record)

    for (
        from_state,
        transition_event,
        to_state,
        guard,
        audit_codes,
        notify_templates,
    ) in _TRANSITIONS:
        if state != from_state or event != transition_event:
            continue
        if not guard(record, tables):
            continue

        return {
            "state": to_state,
            "record": record_copy,
            "audits": list(audit_codes),
            "notifies": list(notify_templates),
            "matched": True,
        }

    return {
        "state": state,
        "record": record_copy,
        "audits": ["WF_NOMATCH"],
        "notifies": [],
        "matched": False,
    }
